// vkernels/kernels/dsa_kpool.hpp
//
// DeepseekSparseAttn (DSA) kpool-cache compress-write — the SM80 / A100
// counterpart to the gfx942 sparse-MLA forward of issue #51 / PR #52, and
// the second half of the GLM-5.3-Flash DSA path that #51 / #52 left on raw
// FP8 Triton (issue #60).
//
// When `index_kpool > 1`, sglang's DeepseekSparseAttn keeps a `kpool-1` live
// tail of recent tokens appended to the fixed `index_topk` columns and held
// in a *persistent* FP8 cache (`torch.float8_e4m3fn`). The cache is written
// by a SEPARATE set of Triton kernels from the attention forward PR #52
// targeted (`sparse_mla_fwd_decode_partial`): the prefill / short-context
// `kpool_assemble_softmax_rotate_write_cache` and the decode
// `kpool_decode_update_and_maybe_write_cache`. On SM80 (A100) Triton cannot
// even declare `*fp8e4nv` in a kernel signature
// (`ValueError("type fp8e4nv not supported in this architecture")`), so
// those kernels JIT-fail on the FIRST forward, before MoE is ever reached.
//
// This file replaces the prefill / short-context
// `_kpool_assemble_softmax_rotate_write_cache_kernel` with a native kernel
// that uses the SAME `gemm_bf16` bf16-storage convention PR #52 established
// (bf16 storage + fp32 accumulation, NO `fp8e4nv` in any signature). The
// decode counterpart follows the identical bf16 pattern; both are reached
// via sglang's `_compress_write` / `_compress_write_extend` (see the
// sglang overlay in cookbook/deployments/llm/bristen/glm-53-flash).
//
// Computation (per pool p = `program_id(0)`, element d in [0, HEAD_DIM)):
// the INDEXER has gathered, for pool p, POOL_SIZE source keys/score tiles —
// the first `n_from_tail[p]` from the recent-token tail buffer (cyclic over
// TAIL_SIZE), the remaining `POOL_SIZE - n_from_tail[p]` from the chunk
// buffer at `chunk_src_start[p]`. Each score tile is HEAD_DIM wide and gets
// the SHARED `ape` bias (`score[slot,d] += ape[slot,d]`). The pool then
// takes a per-ELEMENT base-e softmax over the POOL_SIZE slots (each of the
// HEAD_DIM elements softmaxes INDEPENDENTLY), accumulates the
// softmax-weighted keys, divides by the denominator, applies a normalized
// Hadamard-128, and stores the result as bf16 to the paged cache at `loc[p]`:
//
//   loc_page  = loc[p] / SLOTS_PER_PAGE
//   loc_tok   = loc[p] % SLOTS_PER_PAGE
//   raw[slot,d] = (slot < n_from_tail[p])
//                   ? tail_score[req_pool_idx[p], (tail_logical_base[p]+slot)%TAIL_SIZE, d]
//                   : chunk_score[chunk_src_start[p] + (slot-n_from_tail[p]), d]
//   s[slot,d]   = raw[slot,d] + ape[slot, d]
//   w[slot,d]   = exp(s[slot,d] - max_d) / Sum_slot exp(s[slot,d] - max_d)
//   acc[d]      = Sum_slot w[slot,d] * k[slot,d]            (k gathered like raw)
//   x[d]        = acc[d] / denom[d]                          (denom = Sum_slot w)
//   x           = H128 . x                                   (normalized Hadamard-128)
//   buf[loc_page, loc_tok*HEAD_DIM + d] = bf16(x[d])         (NO fp8 / NO scale)
//
// `head_dim` MUST be 128 (the normalized Hadamard-128 width; GLM-5.3-Flash
// `index_head_dim = 128`). The bf16-storage cache holds
// `SLOTS_PER_PAGE * HEAD_DIM` bf16 values per page with NO scale region
// (the FP8 layout's trailing `SLOTS_PER_PAGE * 4` scale bytes are gone),
// so `buf_numel_per_page = slots_per_page * head_dim` and the footprint is
// 2x the FP8 cache (~fine for the kpool tail, which is small relative to
// the MoE weights + KV cache).
//
// Two-implementation model (mirrors mla.{hpp,cpp,hip} / dsa.{hpp,cpp,hip}
// from issues #21 / #51, and the gemm_bf16 bf16-storage convention):
//   dsa_kpool.cpp  -- CPU reference (oracle), always compiled, in
//                     vkernels::kernels. Two-pass stable per-element softmax,
//                     fp32 throughout, writes the Hadamard'd result as fp32
//                     to the paged buffer (the cross-check target).
//   dsa_kpool.hip  -- HIP kernel (gfx942), compiled with VKERNELS_HAS_HIP.
//                     Online per-element softmax, fp32 accumulation, bf16
//                     storage. Matches the oracle within bf16 tolerance.
//
// The result is grouping-independent (each pool is independent), so one
// kernel block owns exactly one pool row — exactly as the Triton
// `_kpool_assemble_softmax_rotate_write_cache_kernel[(n_pools,)]` grid does.
#include <cstddef>
#include <cstdint>

namespace vkernels::kernels {

// CPU reference (oracle) for the DSA kpool-cache compress-write, prefill /
// short-context path (issue #60). Two-pass numerically-stable per-element
// base-e softmax, fp32 throughout; writes the normalized-Hadamard-128 result
// as fp32 to `buf` at the per-pool write locations (the bf16-storage device
// kernel in dsa.hip is cross-checked against this by rounding the inputs to
// bf16 first, exactly as test_gemm_bf16_correct.hip / test_dsa_correct.hip).
//
// Tensors (head_dim MUST be 128; bf16-storage convention, no scale region):
//   buf        : [n_pages, buf_numel_per_page] fp32 (oracle)
//                buf_numel_per_page = slots_per_page * head_dim (contiguous
//                page geometry; out = loc_page*buf_numel_per_page
//                + loc_tok*head_dim + d, so the bf16 device kernel and the
//                oracle write the SAME logical location).
//   chunk_k    : [num_chunk, head_dim] fp32   (stride (head_dim, 1))
//   chunk_score: [num_chunk, head_dim] fp32
//   tail_k     : [n_req, tail_size, head_dim] fp32 (strides (tail_size*head_dim, head_dim, 1))
//   tail_score : [n_req, tail_size, head_dim] fp32
//   ape        : [pool_size, head_dim] fp32   (shared across pools, stride (head_dim, 1))
//   req_pool_idx : [n_pools] int32   (the request's row in tail_k/tail_score)
//   n_from_tail  : [n_pools] int32   (in [0, pool_size]; leading tail slots)
//   chunk_src_start : [n_pools] int32 (chunk row of the first non-tail slot)
//   tail_logical_base : [n_pools] int32 (cyclic base into TAIL_SIZE)
//   loc        : [n_pools] int64 (flat token index; page=loc/slots_per_page)
//   write_mask : [n_pools] int8  nullable; pool p is SKIPPED (left unwritten)
//                when write_mask[p] == 0 (mirrors the Triton HAS_WRITE_MASK
//                branch; pass nullptr to write every pool).
//
// `n_pools == 0` is a no-op (mirrors the Triton `n_pools == 0` early return).
// Throws std::invalid_argument on a misconfigured caller (head_dim != 128,
// null pointers with work, out aliasing, ...), exactly as dsa_sparse_fwd_cpu
// (issue #57) does — the HIP kernel (dsa.hip::dsa_kpool_compress_write)
// enforces the same preconditions at launch, converting a misconfigured
// caller into a named error instead of a silent hang.
void dsa_kpool_compress_write_cpu(
    int n_pools, int pool_size, int head_dim, int tail_size, int n_req,
    int buf_numel_per_page, int slots_per_page,
    const float* chunk_k, const float* chunk_score,
    const float* tail_k, const float* tail_score,
    const float* ape,
    const int32_t* req_pool_idx, const int32_t* n_from_tail,
    const int32_t* chunk_src_start, const int32_t* tail_logical_base,
    const int64_t* loc, const int8_t* write_mask,
    float* buf);

}  // namespace vkernels::kernels

#if VKERNELS_HAS_HIP
namespace vkernels::kernels::hip {

// HIP kpool-cache compress

