#!/bin/bash
# Diagnostic for issue-60 kpool benchmark follow-up:
#  (a) flake rate of the bs=16/ps=4 decode correctness row (node-dependent)
#  (b) empty-kernel back-to-back dispatch floor (is the ~11us launch overhead?)
set -uo pipefail
cd ~/vkernels-60

echo "=== (a) correctness flake rate: 5 repeats ==="
for i in 1 2 3 4 5; do
  out=$(./build_kpool/meta/benchmarks/test_dsa_kpool_correct 2>&1)
  nfail=$(echo "$out" | grep -c "FAIL$" || true)
  summary=$(echo "$out" | grep "failure(s)" | tail -1)
  failrows=$(echo "$out" | grep "FAIL$" | sed 's/^ *//' | tr '\n' ';')
  echo "run $i: $summary | rows: ${failrows:-none}"
done

echo
echo "=== (b) empty-kernel dispatch floor (batched, reps=2000, same style as bench) ==="
cat > /tmp/empty_bench.hip <<'EOF'
#include <hip/hip_runtime.h>
#include <cstdio>
#include <vector>
#include <algorithm>
// Same launch shape as dsa_kpool kernels (1 warp) and a similar arg count,
// but no work -- isolates per-launch dispatch overhead from kernel execution.
__global__ void empty_kernel(const float* a, float* b, int n, float x, float y, long m) {
  if (threadIdx.x == 9999u) b[0] = a[0] + x + y + (float)n + (float)m;  // never taken
}
int main() {
  hipEvent_t s, e;
  hipEventCreate(&s); hipEventCreate(&e);
  float* a; float* b;
  hipMalloc(&a, 16); hipMalloc(&b, 16);
  auto launch = [&]{ hipLaunchKernelGGL(empty_kernel, dim3(1), dim3(64), 0, 0, a, b, 5, 1.0f, 2.0f, 7L); };
  const int reps = 2000;
  for (int i = 0; i < 5; ++i) { for (int r = 0; r < reps; ++r) launch(); }
  hipDeviceSynchronize();
  std::vector<float> per;
  for (int smp = 0; smp < 30; ++smp) {
    hipEventRecord(s);
    for (int r = 0; r < reps; ++r) launch();
    hipEventRecord(e);
    hipEventSynchronize(e);
    float ms = 0; hipEventElapsedTime(&ms, s, e);
    per.push_back(ms * 1000.0f / reps);
  }
  std::sort(per.begin(), per.end());
  double sum = 0; for (double v : per) sum += v;
  printf("empty 1-warp kernel: min=%.2f med=%.2f mean=%.2f us/launch (reps=%d)\n",
         per[0], per[per.size()/2], sum / per.size(), reps);
  hipFree(a); hipFree(b);
  return 0;
}
EOF
hipcc -O3 -std=c++17 /tmp/empty_bench.hip -o /tmp/empty_bench && /tmp/empty_bench
echo "===== DIAG DONE ====="

