#!/bin/bash
# Diagnostic 2 for issue-60 follow-up:
#  (a) empty-kernel back-to-back dispatch floor (is the ~11us launch overhead?)
#  (b) kpool decode flake repro: 30 iters x {flaky row, disjoint-tail bisect,
#      passing row}, with argmax element reporting on mismatch
set -uo pipefail
cd ~/vkernels-60

echo "=== (a) empty-kernel dispatch floor (batched, reps=2000) ==="
cat > /tmp/empty_bench.hip <<'EOF'
#include <hip/hip_runtime.h>
#include <cstdio>
#include <vector>
#include <algorithm>
__global__ void empty_kernel(const float* a, float* b, int n, float x, float y, long m) {
  if (threadIdx.x == 9999u) b[0] = a[0] + x + y + (float)n + (float)m;  // never taken
}
int main() {
  hipEvent_t s, e;
  hipEventCreate(&s); hipEventCreate(&e);
  float* a; float* b;
  hipMalloc(&a, 16); hipMalloc(&b, 16);
  auto launch = [&]{ hipLaunchKernelGGL(empty_kernel, dim3(1), dim3(64), 0, 0, a, b, 5, 1.0f, 2.0f, 7L); };
  const int reps = 2000;
  for (int i = 0; i < 5; ++i) { for (int r = 0; r < reps; ++r) launch(); }
  hipDeviceSynchronize();
  std::vector<float> per;
  for (int smp = 0; smp < 30; ++smp) {
    hipEventRecord(s);
    for (int r = 0; r < reps; ++r) launch();
    hipEventRecord(e);
    hipEventSynchronize(e);
    float ms = 0; hipEventElapsedTime(&ms, s, e);
    per.push_back(ms * 1000.0f / reps);
  }
  std::sort(per.begin(), per.end());
  double sum = 0; for (double v : per) sum += v;
  printf("empty 64-thread kernel: min=%.2f med=%.2f mean=%.2f us/launch (reps=%d)\n",
         per[0], per[per.size()/2], sum / per.size(), reps);
  hipFree(a); hipFree(b);
  return 0;
}
EOF
