static GpuInfo get_gpu_info() {
  hipDeviceProp_t p;
  check_hip(hipGetDeviceProperties(&p, 0), "props");
  GpuInfo i;
  i.name = p.name;
  if (std::strstr(p.gcnArchName, "gfx942"))      { i.arch = 942; i.tflops = 1307; i.bw = 5300; i.tflops_unit = "bf16"; }
  else if (std::strstr(p.gcnArchName, "gfx90a")) { i.arch = 90;  i.tflops = 383;  i.bw = 3200; i.tflops_unit = "bf16"; }
  else if (std::strstr(p.name, "A100")) {
    // A100-SXM4-80GB (HIP-on-NVIDIA port): the kpool kernels are fp32
    // CUDA-core math (no tensor units), so the honest compute roof is the
    // fp32 FMA peak (~19.5 TFLOP/s), not the bf16 TC peak; HBM2e ~2039 GB/s.
    i.arch = 80; i.tflops = 19.5; i.bw = 2039; i.tflops_unit = "fp32";
  }
  else                                            { i.arch = 0;   i.tflops = 100;  i.bw = 1000; }
  return i;
}
// meta/benchmarks/bench_dsa_kpool.hip
//
// Micro-benchmark for the DSA kpool-cache compress/write kernels (issue #60)
// on AMD gfx942 (MI300A): the bf16-storage / no-fp8e4nv HIP replacements for
// sglang's ``kpool_assemble_softmax_rotate_write_cache`` (PREFILL) and
// ``kpool_decode_update_and_maybe_write_cache`` (DECODE).
//
// For each GLM-5.3-Flash serving shape it reports, against the MI300A roof
// (gfx942: ~1307 TFLOP/s bf16, ~5300 GB/s HBM3, ridge ~247 FLOP/B):
//

int main() {
  const GpuInfo info = get_gpu_info();
  std::printf("=== DSA kpool-cache compress/write (gfx942) ===\n");
  std::printf("  device: %s (arch %d), roof %.0f TFLOP/s %s, "
              "%.0f GB/s HBM\n",
              info.name.c_str(), info.arch, info.tflops, info.tflops_unit,
              info.bw);

  hipEvent_t start, stop;
  check_hip(hipEventCreate(&start), "ev_start");
  check_hip(hipEventCreate(&stop),  "ev_stop");

  bench_assemble(info, start, stop);

